#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-or-later
# Copyright (C) 2026 diskOS contributors
# diskos-ota-release.sh - build and verify the 6 signed diskos-ota-* assets
# required by in-app "Update diskOS" (ui/ota.c) for a GitHub Release.
#
# Usage:
#   ./tools/diskos-ota-release.sh [--version N.N.N] [--epoch N] [--save-epoch]
#                                 [--bin PATH] [--out DIR] [--channel NAME]
#
# Requires:
#   - signing/root_priv.pem, signing/leaf_priv.pem, signing/leaf_pub.pem
#     (generated by ./tools/diskos-ota-keygen.sh; root_pub must match payload/diskos-root.pub.pem)
#   - openssl, sha256sum, wc, tr

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
SIGN_DIR="$REPO_ROOT/signing"
ROOT_PUB="$REPO_ROOT/payload/diskos-root.pub.pem"
VERIFIER="$REPO_ROOT/payload/diskos-verify.sh"

VERSION=""
EPOCH=""
SAVE_EPOCH=0
BIN=""
OUT_DIR=""
CHANNEL="stable"

usage() {
    cat <<EOF
Usage: $0 [--version N.N.N] [--epoch N] [--save-epoch] [--bin PATH] [--out DIR] [--channel NAME]

Generates and verifies the 6 GitHub Release OTA assets:
  diskos-ota-keyauthz
  diskos-ota-keyauthz.sig
  diskos-ota-leafpub.pem
  diskos-ota-update.manifest
  diskos-ota-update.manifest.sig
  diskos-ota-mq_ui
EOF
}

while [ $# -gt 0 ]; do
    case "$1" in
        --version)
            [ $# -ge 2 ] || { echo "ERROR: missing value for $1" >&2; exit 1; }
            VERSION="$2"
            shift 2
            ;;
        --epoch)
            [ $# -ge 2 ] || { echo "ERROR: missing value for $1" >&2; exit 1; }
            EPOCH="$2"
            shift 2
            ;;
        --save-epoch)
            SAVE_EPOCH=1
            shift
            ;;
        --bin)
            [ $# -ge 2 ] || { echo "ERROR: missing value for $1" >&2; exit 1; }
            BIN="$2"
            shift 2
            ;;
        --out)
            [ $# -ge 2 ] || { echo "ERROR: missing value for $1" >&2; exit 1; }
            OUT_DIR="$2"
            shift 2
            ;;
        --channel)
            [ $# -ge 2 ] || { echo "ERROR: missing value for $1" >&2; exit 1; }
            CHANNEL="$2"
            shift 2
            ;;
        -h|--help)
            usage
            exit 0
            ;;
        *)
            echo "ERROR: unknown option: $1" >&2
            usage >&2
            exit 1
            ;;
    esac
done

if [ -z "$VERSION" ]; then
    VERSION="$(sed -n 's/^#define[[:space:]]\+DISKOS_VERSION[[:space:]]\+"\([^"]*\)"/\1/p' "$REPO_ROOT/ui/version.h" | head -n 1)"
fi
if ! printf '%s' "$VERSION" | grep -Eq '^[0-9]{1,5}\.[0-9]{1,5}\.[0-9]{1,5}$'; then
    echo "ERROR: version '$VERSION' must match strict N.N.N (ota_ver_parse)" >&2
    exit 1
fi

if ! printf '%s' "$CHANNEL" | grep -Eq '^[A-Za-z0-9._-]+$'; then
    echo "ERROR: invalid channel '$CHANNEL'" >&2
    exit 1
fi

if [ -z "$BIN" ]; then
    BIN="$REPO_ROOT/payload/mq_ui"
fi
if [ ! -f "$BIN" ]; then
    echo "ERROR: mq_ui binary not found: $BIN" >&2
    exit 1
fi

for req in "$SIGN_DIR/root_priv.pem" "$SIGN_DIR/leaf_priv.pem" "$SIGN_DIR/leaf_pub.pem" "$ROOT_PUB" "$VERIFIER"; do
    if [ ! -f "$req" ]; then
        echo "ERROR: required file missing: $req" >&2
        exit 1
    fi
done

if [ -f "$SIGN_DIR/root_pub.pem" ] && ! cmp -s "$SIGN_DIR/root_pub.pem" "$ROOT_PUB"; then
    echo "ERROR: $SIGN_DIR/root_pub.pem does not match $ROOT_PUB" >&2
    exit 1
fi

EPOCH_FILE="$SIGN_DIR/.epoch"
EPOCH_FROM_FILE=0
if [ -z "$EPOCH" ]; then
    EPOCH_FROM_FILE=1
    if [ -f "$EPOCH_FILE" ]; then
        CUR_EPOCH="$(tr -d ' \t\r\n' < "$EPOCH_FILE")"
        if ! printf '%s' "$CUR_EPOCH" | grep -Eq '^[0-9]+$'; then
            echo "ERROR: invalid epoch in $EPOCH_FILE: '$CUR_EPOCH'" >&2
            exit 1
        fi
        EPOCH=$((CUR_EPOCH + 1))
    else
        EPOCH=8
    fi
elif ! printf '%s' "$EPOCH" | grep -Eq '^[0-9]+$' || [ "$EPOCH" -lt 1 ]; then
    echo "ERROR: invalid --epoch '$EPOCH'" >&2
    exit 1
fi

if [ -z "$OUT_DIR" ]; then
    OUT_DIR="$REPO_ROOT/build/dist/ota-v${VERSION}"
fi
mkdir -p "$OUT_DIR"

TMP_VERIFY="$(mktemp -d "/tmp/diskos-ota-verify.XXXXXX")"
trap 'rm -rf "$TMP_VERIFY"' EXIT

cp "$SIGN_DIR/leaf_pub.pem" "$OUT_DIR/diskos-ota-leafpub.pem"
cp "$BIN" "$OUT_DIR/diskos-ota-mq_ui"

LEAF_HASH="$(sha256sum "$OUT_DIR/diskos-ota-leafpub.pem" | cut -d' ' -f1)"
UI_HASH="$(sha256sum "$OUT_DIR/diskos-ota-mq_ui" | cut -d' ' -f1)"
UI_SIZE="$(wc -c < "$OUT_DIR/diskos-ota-mq_ui" | tr -d ' ')"

cat > "$OUT_DIR/diskos-ota-keyauthz" <<EOF
diskos-keyauthz-v1
keyid=release-key
keyepoch=1
role=tier-a
pubkey_sha256=${LEAF_HASH}
EOF
openssl dgst -sha256 -sign "$SIGN_DIR/root_priv.pem" \
    -out "$OUT_DIR/diskos-ota-keyauthz.sig" \
    "$OUT_DIR/diskos-ota-keyauthz"

cat > "$OUT_DIR/diskos-ota-update.manifest" <<EOF
diskos-update-v1
component=mq_ui
epoch=${EPOCH}
version=${VERSION}
size=${UI_SIZE}
sha256=${UI_HASH}
channel=${CHANNEL}
EOF
openssl dgst -sha256 -sign "$SIGN_DIR/leaf_priv.pem" \
    -out "$OUT_DIR/diskos-ota-update.manifest.sig" \
    "$OUT_DIR/diskos-ota-update.manifest"

cp "$OUT_DIR/diskos-ota-keyauthz" "$TMP_VERIFY/keyauthz"
cp "$OUT_DIR/diskos-ota-keyauthz.sig" "$TMP_VERIFY/keyauthz.sig"
cp "$OUT_DIR/diskos-ota-leafpub.pem" "$TMP_VERIFY/leafpub.pem"
cp "$OUT_DIR/diskos-ota-update.manifest" "$TMP_VERIFY/update.manifest"
cp "$OUT_DIR/diskos-ota-update.manifest.sig" "$TMP_VERIFY/update.manifest.sig"

sh "$VERIFIER" "$ROOT_PUB" 1 8 "$TMP_VERIFY" "$OUT_DIR/diskos-ota-mq_ui"

if [ "$EPOCH_FROM_FILE" -eq 1 ] || [ "$SAVE_EPOCH" -eq 1 ]; then
    printf '%s\n' "$EPOCH" > "$EPOCH_FILE"
fi

echo ""
echo "Signed OTA bundle ready in: $OUT_DIR"
echo "Upload all 6 assets to GitHub Release v${VERSION}:"
echo "  gh release upload v${VERSION} \\"
echo "    $OUT_DIR/diskos-ota-keyauthz \\"
echo "    $OUT_DIR/diskos-ota-keyauthz.sig \\"
echo "    $OUT_DIR/diskos-ota-leafpub.pem \\"
echo "    $OUT_DIR/diskos-ota-update.manifest \\"
echo "    $OUT_DIR/diskos-ota-update.manifest.sig \\"
echo "    $OUT_DIR/diskos-ota-mq_ui --clobber"
